 		WARN_ON(rcu_access_pointer(dev->ip_ptr));
 		WARN_ON(rcu_access_pointer(dev->ip6_ptr));
 
+		if (!strncmp(current->comm, "syzrepro1", 9)) {
+			mdelay(1);
+		}
 		netdev_name_node_alt_flush(dev);
 		netdev_name_node_free(dev->name_node);
