> +       list_for_each_safe(p, n, &queue->pending_dqbufs) {
> +               struct virtio_media_buffer *dqbuf =
> +                       list_entry(p, struct virtio_media_buffer, list);
> +
> +               list_del(&dqbuf->list);
> +       }
