 	if (!fw || fw->size < sizeof(struct elf32_hdr))
@@ -1287,24 +1290,24 @@ static struct se_fw_hdr *geni_find_protocol_fw(struct geni_se *se, const struct
 		if (phdr->p_filesz < sizeof(struct se_fw_hdr))
